import { computed, ref } from "vue";
import {
  XhButton,
  XhListboxRoot,
  XhPopoverContent,
  XhPopoverPositioner,
  XhPopoverRoot,
  XhPopoverTrigger,
} from "@xihan-ui/vue";

const songs = [
  { value: "song1", label: "起风了" },
  { value: "song2", label: "夜空中最亮的星" },
  { value: "song3", label: "海阔天空（暂不可选）", disabled: true },
  { value: "song4", label: "晴天" },
];

const value = ref<string[]>(["song1"]);
